def _name(shape, filters, kernel, strides, padding):
    h, w, c = shape
    return (f"conv2d_k{kernel[0]}x{kernel[1]}_s{strides[0]}x{strides[1]}_{padding}_"
            f"{h}x{w}x{c}_oc{filters}")


CASES = {}
for _layer in _LAYERS:
    _key = _name(*_layer)
    if _key in CASES:
        raise ValueError(f"conv2d_layers: {_key} is listed twice")
    CASES[_key] = conv2d(*_layer)

